// MVP Heuristic Parser & Context Extractor
// NOTE: In production, this can be coupled with an LLM classification node to handle edge-case international layouts.
const lead = $('Loop Over Leads').item.json;
const rawHtml = typeof $json.data === 'string' && $json.data.length > 50 ? $json.data : (lead.mock_html || '');

// 1. Clean HTML tags
const cleanText = rawHtml
  .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, ' ')
  .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// 2. Extract Metadata
const titleMatch = rawHtml.match(/<title[^>]*>([^<]+)<\/title>/i);
const metaDescMatch = rawHtml.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["']/i);
const title = titleMatch ? titleMatch[1].trim() : lead.company_name;
const metaDescription = metaDescMatch ? metaDescMatch[1].trim() : 'No meta description found';

// 3. Heuristic Signal Detection
const lowerText = cleanText.toLowerCase();
const hasOnlineBooking = /(book\s*online|instant\s*booking|schedule\s*appointment|calendly|zocdoc|janeapp|online\s*scheduler)/i.test(lowerText);
const hasLiveChat = /(chat\s*with\s*us|live\s*chat|intercom|tidio|crisp|tawk|whatsapp)/i.test(lowerText);
const hasPhoneCallOnly = /(call\s*us|call\s*during\s*office|call\s*our\s*front\s*desk|call\s*our\s*receptionist|leave\s*a\s*voicemail)/i.test(lowerText) && !hasOnlineBooking;
const hasSlowResponseWarning = /(2-3\s*business\s*days|within\s*48\s*hours|reply\s*shortly)/i.test(lowerText);

let identifiedProblem = "No automated 24/7 patient inquiry or direct calendar scheduling visible on homepage.";
if (hasPhoneCallOnly) {
  identifiedProblem = "Clinic relies strictly on phone calls during office hours; lacks instant 24/7 automated appointment booking for after-hours patient inquiries.";
} else if (hasSlowResponseWarning) {
  identifiedProblem = "Contact forms have a multi-day response lag (2-3 business days), leading to high patient churn to competing local clinics.";
} else if (!hasLiveChat) {
  identifiedProblem = "No immediate live chat assistant on landing page to answer patient questions regarding insurance coverage and treatment pricing.";
}

return [{
  json: {
    id: lead.id,
    company_name: lead.company_name,
    website_url: lead.website_url,
    city: lead.city,
    contact_name: lead.contact_name,
    contact_title: lead.contact_title,
    contact_email: lead.contact_email,
    specialization: lead.specialization,
    page_title: title,
    meta_description: metaDescription,
    text_snippet: cleanText.slice(0, 1200),
    signals: {
      has_online_booking: hasOnlineBooking,
      has_live_chat: hasLiveChat,
      has_phone_only: hasPhoneCallOnly
    },
    identified_problem: identifiedProblem
  }
}];

