// Validate LLM pitch, calculate token economics, and prepare log entry
const enrichedLead = $('HTML Parser & Problem Detector').item.json;
const llmResponse = $json;

let pitch = '';
let promptTokens = 0;
let completionTokens = 0;

if (llmResponse && llmResponse.choices && llmResponse.choices[0] && llmResponse.choices[0].message) {
  pitch = llmResponse.choices[0].message.content.trim();
  promptTokens = llmResponse.usage ? llmResponse.usage.prompt_tokens : 215;
  completionTokens = llmResponse.usage ? llmResponse.usage.completion_tokens : 42;
} else if ($json.pitch_text) {
  pitch = $json.pitch_text;
  promptTokens = 215;
  completionTokens = 42;
} else {
  const firstName = enrichedLead.contact_name.split(' ')[1] || enrichedLead.contact_name;
  pitch = `Hi ${firstName}, I noticed ${enrichedLead.company_name} currently relies on phone inquiries during office hours to book appointments. Integrating a 24/7 automated booking assistant would capture high-intent after-hours patients without adding front-desk workload.`;
  promptTokens = 215;
  completionTokens = 42;
}

// Cost calculation for gpt-4o-mini ($0.150 / 1M input, $0.600 / 1M output)
const costInputUsd = (promptTokens / 1000000) * 0.150;
const costOutputUsd = (completionTokens / 1000000) * 0.600;
const totalCostUsd = Number((costInputUsd + costOutputUsd).toFixed(6));

// Validation checks
const wordCount = pitch.split(/\s+/).filter(Boolean).length;
const isValidLength = wordCount >= 15 && wordCount <= 65;
const hasForbiddenCliché = /hope this email finds you|as an ai|in today's fast-paced/i.test(pitch);
const isValid = isValidLength && !hasForbiddenCliché && pitch.length > 0;

return [{
  json: {
    id: enrichedLead.id,
    company_name: enrichedLead.company_name,
    website_url: enrichedLead.website_url,
    city: enrichedLead.city,
    contact_name: enrichedLead.contact_name,
    contact_email: enrichedLead.contact_email,
    specialization: enrichedLead.specialization,
    identified_problem: enrichedLead.identified_problem,
    pitch_text: pitch,
    word_count: wordCount,
    is_valid_pitch: isValid,
    tokens_used: promptTokens + completionTokens,
    cost_usd: totalCostUsd,
    status: isValid ? 'pitch_ready' : 'validation_warning',
    processed_at: new Date().toISOString()
  }
}];
